ROLES = {
    'читатель':   {'read'},
    'редактор':   {'read', 'write'},
    'админ':      {'read', 'write', 'delete', 'grant'},
}

users = {'Азиз': 'редактор', 'Али': 'читатель'}

def can(user, action):
    role = users.get(user)
    return action in ROLES.get(role, set())

for user in ['Азиз', 'Али', 'Неизвестный']:
    for action in ['read', 'delete']:
        mark = 'да ' if can(user, action) else 'нет'
        print(f"{user:12} {action:7} {mark}")

STAGES = ['обнаружение', 'локализация', 'устранение', 'восстановление', 'разбор']

def next_stage(done):
    for s in STAGES:
        if s not in done:
            return s
    return None

done = ['обнаружение', 'локализация']
print('сделано:', done)
print('дальше: ', next_stage(done))
print('после всего:', next_stage(STAGES))

