def mask(value, keep=4):
    """Оставляем хвост, остальное прячем — чтобы событие можно было опознать."""
    text = str(value)
    if len(text) <= keep:
        return "*" * len(text)
    return "*" * (len(text) - keep) + text[-keep:]

