def domain_of(address):
    return address.rsplit("@", 1)[-1].lower()

def trusted(address, base):
    d = domain_of(address)
    # только сам домен или его настоящий поддомен
    return d == base or d.endswith("." + base)

for s in senders:
    mark = "свой " if trusted(s, TRUSTED) else "ЧУЖОЙ"
    print(f"{mark}  {s}")
